wall_plate_height = 50;      // Height of the wall mounting plate
wall_plate_thickness = 5;    // Thickness of the mounting plate

hook_thickness = 8;          // Thickness of the hook arm (for strength)
hook_width = 25;             // Width of the hook
hook_depth = 35;             // How far the hook extends from the wall
hook_inner_radius = 12;      // Inner radius of the hook curve
hook_tip_length = 10;        // Length of the upward tip to prevent towel slipping

// M3 flat head screw hole
m3_hole_dia = 3.4;          // Clearance hole for M3 screw
m3_head_dia = 6.7;          // M3 flat head diameter (countersink)
m3_head_depth = 1.8;        // Depth of countersink

// Fillet/reinforcement
gusset_size = 15;            // Size of the reinforcement gusset

module wall_plate() {
    // Rounded rectangle mounting plate
    hull() {
        for (x = [-wall_plate_width/2 + 4, wall_plate_width/2 - 4])
            for (z = [4, wall_plate_height - 4])
                translate([x, wall_plate_thickness/2, z])
                    rotate([90, 0, 0])
                        cylinder(r=4, h=wall_plate_thickness, center=true);
    }
}

module screw_hole() {
    // Position screw hole in upper portion of plate for stability
    translate([0, 0, wall_plate_height - 15]) {
        // Through hole
        translate([0, wall_plate_thickness + 1, 0])
            rotate([90, 0, 0])
                cylinder(d=m3_hole_dia, h=wall_plate_thickness + 2);
        // Countersink on the back (wall side)
        translate([0, wall_plate_thickness + 0.01, 0])
            rotate([90, 0, 0])
                cylinder(d1=m3_head_dia, d2=m3_hole_dia, h=m3_head_depth);
    }
}

module hook_arm() {
    // The main hook body extending from the plate
    // Consists of: horizontal arm + curved hook + upward tip

    arm_start_z = 5;  // Start height of the arm from bottom of plate

    translate([0, wall_plate_thickness, arm_start_z]) {
        // Horizontal arm extending outward
        translate([-hook_width/2, 0, 0])
            cube([hook_width, hook_depth - hook_inner_radius - hook_thickness/2, hook_thickness]);

        // Curved hook section (180-degree curve going down then back)
        translate([0, hook_depth - hook_inner_radius - hook_thickness/2, 0]) {
            // The curve
            rotate([0, 0, 0])
            translate([0, 0, hook_thickness/2])
            rotate([0, 90, 0])
            translate([0, 0, -hook_width/2])
            difference() {
                // Outer cylinder
                cylinder(r=hook_inner_radius + hook_thickness, h=hook_width);
                // Inner cylinder (hollow)
                translate([0, 0, -1])
                    cylinder(r=hook_inner_radius, h=hook_width + 2);
                // Cut to make it a half-pipe (only bottom half - the hook curve)
                translate([-hook_inner_radius - hook_thickness - 1, -hook_inner_radius - hook_thickness - 1, -1])
                    cube([2*(hook_inner_radius + hook_thickness) + 2, hook_inner_radius + hook_thickness + 1, hook_width + 2]);
            }

            // Upward tip to prevent towel from slipping off
            translate([-hook_width/2, -(hook_inner_radius + hook_thickness), hook_thickness/2])
                rotate([0, 90, 0])
                    translate([0, 0, 0])
                        cube([hook_tip_length, hook_thickness, hook_width]);
        }
    }
}

module gusset() {
    // Triangular reinforcement between plate and arm
    arm_start_z = 5;
    translate([0, wall_plate_thickness, arm_start_z + hook_thickness]) {
        // Left gusset
        translate([-hook_width/2, 0, 0])
        rotate([0, -90, 0])
        linear_extrude(height=2)
            polygon([[0, 0], [0, gusset_size], [gusset_size, 0]]);

        // Right gusset  
        translate([hook_width/2 + 2, 0, 0])
        rotate([0, -90, 0])
        linear_extrude(height=2)
            polygon([[0, 0], [0, gusset_size], [gusset_size, 0]]);

        // Center fill gusset
        translate([-hook_width/2, 0, 0])
            linear_extrude(height=gusset_size)
                polygon([[0, 0], [hook_width, 0], [hook_width, gusset_size], [0, gusset_size]]);

        // Taper the gusset - subtract to make triangular
        translate([-hook_width/2 - 1, 0, 0])
            rotate([0, 0, 0])
                linear_extrude(height=gusset_size + 1)
                    polygon([[0, gusset_size], [hook_width + 2, gusset_size], [hook_width + 2, gusset_size + 1], [0, gusset_size + 1]]);
    }
}

module gusset_solid() {
    // Solid triangular reinforcement
    arm_start_z = 5;
    translate([-hook_width/2, wall_plate_thickness, arm_start_z + hook_thickness]) {
        linear_extrude(height=hook_width)
            polygon([[0, 0], [gusset_size, 0], [0, gusset_size]]);
    }
    // Mirror for the other side - actually this is one solid piece
}

module reinforced_gusset() {
    arm_start_z = 5;
    // Triangular gusset profile extruded along width
    translate([0, wall_plate_thickness, arm_start_z + hook_thickness])
    rotate([0, -90, 0])
    translate([0, 0, -hook_width/2])
    linear_extrude(height=hook_width)
        polygon([[0, 0], [gusset_size, 0], [0, gusset_size]]);
}

// Final assembly
difference() {
    union() {
        wall_plate();
        hook_arm();
        reinforced_gusset();
    }
    screw_hole();
}
'}

{'content': "// Wall-mounted Towel Hook - M3 flat head screw mounting
// Designed for 3D printing with maximum strength
// Print orientation: flat plate on the bed, hook pointing up

$fn = 100;

// === Parameters ===
// Wall plate
plate_w = 32;          // Width of mounting plate
plate_h = 55;          // Height of mounting plate  
plate_t = 5;           // Thickness of mounting plate
plate_r = 5;           // Corner radius of plate

// Hook profile
hook_w = 22;           // Width of hook body
hook_arm_len = 30;     // Length of horizontal arm from wall
hook_t = 8;            // Thickness of hook cross-section
hook_curve_r = 14;     // Inner radius of the J-curve
hook_tip_len = 18;     // How far the tip extends upward
hook_tip_angle = 15;   // Slight outward angle on tip (degrees)

// Gusset (reinforcement triangle)
gusset_h = 22;         // Height of triangular gusset

// M3 flat head screw
m3_clear = 3.4;        // M3 clearance diameter
m3_head_d = 6.8;       // Flat head top diameter
m3_head_depth = 2.0;   // Countersink depth
screw_z = plate_h - 14; // Screw position (upper area for leverage)

// === Modules ===

// Rounded rectangle 2D profile for the plate
module rounded_rect(w, h, r) {
    offset(r) offset(-r) square([w, h], center=true);
}

// Wall mounting plate
module wall_plate() {
    translate([0, plate_t/2, plate_h/2])
        rotate([90, 0, 0])
            linear_extrude(height=plate_t, center=true)
                rounded_rect(plate_w, plate_h, plate_r);
}

// M3 countersunk screw hole (from back through to front)
module screw_hole() {
    translate([0, 0, screw_z]) {
        // Through hole
        rotate([-90, 0, 0])
            translate([0, 0, -1])
                cylinder(d=m3_clear, h=plate_t + 2);
        // Countersink on back face (cone for flat head)
        rotate([-90, 0, 0])
            translate([0, 0, -0.01])
                cylinder(d1=m3_head_d, d2=m3_clear, h=m3_head_depth);
    }
}

// Hook arm + J-curve + tip as a single solid
module hook_body() {
    arm_z = plate_t;  // Start from front face of plate
    base_h = 4;       // Bottom of arm aligns here (z)

    // We'll build the hook profile in 2D (in YZ plane) then extrude along X
    // Profile: horizontal arm -> 180° curve down and back -> upward tip

    translate([0, 0, 0]) {
        // Horizontal arm
        translate([-hook_w/2, plate_t, base_h])
            cube([hook_w, hook_arm_len, hook_t]);

        // Curved J section
        curve_center_y = plate_t + hook_arm_len;
        curve_center_z = base_h + hook_t / 2;

        translate([0, curve_center_y, curve_center_z])
        rotate([0, 90, 0])
        translate([0, 0, -hook_w/2])
        linear_extrude(height=hook_w) {
            difference() {
                circle(r = hook_curve_r + hook_t/2);
                circle(r = hook_curve_r - hook_t/2);
                // Keep only the right half (positive x in this 2D space = positive y in 3D)
                translate([-(hook_curve_r + hook_t), -(hook_curve_r + hook_t)])
                    square([2*(hook_curve_r + hook_t), hook_curve_r + hook_t]);
            }
        }

        // Upward tip (anti-slip)
        tip_base_y = curve_center_y;
        tip_base_z = curve_center_z - hook_curve_r - hook_t/2;

        // Tip goes upward with a slight outward lean
        translate([0, tip_base_y, tip_base_z])
        translate([-hook_w/2, -hook_t, 0])
        rotate([hook_tip_angle, 0, 0])
        translate([0, 0, 0])
            cube([hook_w, hook_t, hook_tip_len]);

        // Rounded tip end
        translate([0, tip_base_y, tip_base_z])
        translate([0, -hook_t/2, 0])
        rotate([hook_tip_angle, 0, 0])
        translate([0, 0, hook_tip_len])
        rotate([0, 90, 0])
        translate([0, 0, -hook_w/2])
            // Rounded cap
            intersection() {
                cylinder(d=hook_t, h=hook_w);
                translate([0, -hook_t/2, 0])
                    cube([hook_t, hook_t, hook_w]);
            }
    }
}

// Reinforcement gussets (triangular supports between plate and arm)
module gussets() {
    base_h = 4 + hook_t;  // Top of the arm

    // Solid triangular gusset extruded to hook width
    translate([-hook_w/2, plate_t, base_h])
        rotate([0, 90, 0])
            linear_extrude(height=hook_w)
                polygon([[0, 0], [0, gusset_h * 0.6], [gusset_h, 0]]);

    // Additional side gussets for extra strength
    for (mx = [-1, 1]) {
        translate([mx * hook_w/2, plate_t, 4])
            rotate([0, mx > 0 ? 0 : 180, 0])
                translate([0, 0, 0])
                    linear_extrude(height=3)
                        polygon([[0, 0], [0, gusset_h * 0.8], [gusset_h, 0]]);
    }
}

// Bottom support (connects lower plate to arm underside)
module bottom_support() {
    // Small fillet under the arm
    translate([-hook_w/2, plate_t, 0])
        cube([hook_w, 6, 4]);
}

// === Assembly ===
difference() {
    union() {
        wall_plate();
        hook_body();
        gussets();
        bottom_support();
    }
    screw_hole();
}
"}

{'content': '// Wall-mounted Towel Hook - M3 flat head screw mounting
// Designed for 3D printing with maximum strength
// Print with plate flat on bed, hook extending upward

$fn = 100;

// === Parameters ===
// Wall plate
plate_w = 34;           // Width of mounting plate
plate_h = 55;           // Height of mounting plate  
plate_t = 5;            // Thickness of mounting plate
plate_r = 5;            // Corner radius of plate

// Hook dimensions
hook_w = 22;            // Width of hook body
hook_arm_len = 32;      // Length of horizontal arm from wall
hook_t = 8;             // Thickness of hook cross-section
hook_curve_r = 13;      // Inner radius of the J-curve
hook_tip_len = 20;      // How far the tip extends upward
hook_tip_angle = 12;    // Slight outward angle on tip (degrees)
arm_bottom_z = 5;       // Z position of arm bottom

// Gusset (reinforcement)
gusset_depth = 20;      // How far gusset extends along arm
gusset_height = 25;     // How high gusset goes on plate

// M3 flat head screw
m3_clear = 3.4;         // M3 clearance diameter
m3_head_d = 6.8;        // Flat head top diameter  
m3_head_depth = 2.0;    // Countersink depth
screw_z = plate_h - 15; // Screw position (upper area)

// === Modules ===

module rounded_rect_2d(w, h, r) {
    offset(r) offset(-r) square([w, h], center=true);
}

// Wall mounting plate with rounded corners
module wall_plate() {
    translate([0, plate_t/2, plate_h/2])
        rotate([90, 0, 0])
            linear_extrude(height=plate_t, center=true)
                rounded_rect_2d(plate_w, plate_h, plate_r);
}

// M3 countersunk screw hole
module screw_hole() {
    translate([0, 0, screw_z]) {
        // Through hole
        rotate([-90, 0, 0])
            translate([0, 0, -1])
                cylinder(d=m3_clear, h=plate_t + 2);
        // Countersink cone on back face
        rotate([-90, 0, 0])
            translate([0, 0, -0.01])
                cylinder(d1=m3_head_d, d2=m3_clear, h=m3_head_depth + 0.01);
    }
}

// 2D hook profile (in YZ plane) - will be extruded along X
module hook_profile_2d() {
    arm_top = arm_bottom_z + hook_t;
    curve_cy = plate_t + hook_arm_len;
    curve_cz = arm_bottom_z + hook_t/2;
    r_outer = hook_curve_r + hook_t/2;
    r_inner = hook_curve_r - hook_t/2;

    union() {
        // Horizontal arm
        translate([plate_t, arm_bottom_z])
            square([hook_arm_len, hook_t]);

        // J-curve (180 degrees)
        translate([curve_cy, curve_cz])
            difference() {
                circle(r=r_outer);
                circle(r=r_inner);
                // Remove top half to get bottom semicircle
                translate([-r_outer-1, 0])
                    square([2*r_outer+2, r_outer+1]);
            }

        // Upward tip
        tip_base_y = curve_cy;
        tip_base_z = curve_cz - r_outer;

        translate([tip_base_y, tip_base_z])
            rotate(180 + hook_tip_angle)
                translate([-hook_t/2, 0])
                    square([hook_t, hook_tip_len]);

        // Rounded tip end
        translate([tip_base_y, tip_base_z])
            rotate(180 + hook_tip_angle)
                translate([0, hook_tip_len])
                    circle(d=hook_t);
    }
}

// Main hook body - extrude 2D profile
module hook_body() {
    translate([0, 0, 0])
    rotate([90, 0, 90])
    translate([0, 0, -hook_w/2])
        linear_extrude(height=hook_w)
            hook_profile_2d();
}

// Smooth reinforcement gusset between plate and arm
module gusset() {
    arm_top_z = arm_bottom_z + hook_t;

    // Main triangular gusset (full width of hook)
    translate([-hook_w/2, plate_t, arm_top_z])
        rotate([0, 90, 0])
            linear_extrude(height=hook_w)
                polygon([
                    [0, 0],
                    [0, gusset_depth],
                    [-gusset_height, 0]
                ]);

    // Wider flared gussets on the sides for lateral stiffness
    gusset_flare = (plate_w - hook_w) / 2;  // Extra width per side

    for (side = [-1, 1]) {
        translate([side * hook_w/2, plate_t, arm_top_z])
            rotate([0, side > 0 ? 0 : 180, 0])
                linear_extrude(height=gusset_flare)
                    polygon([
                        [0, 0],
                        [0, gusset_depth * 0.5],
                        [-gusset_height * 0.7, 0]
                    ]);
    }

    // Under-arm support (small block bridging plate to arm underside)
    translate([-hook_w/2, plate_t, 0])
        cube([hook_w, 5, arm_bottom_z]);

    // Under flares
    for (side = [-1, 1]) {
        hull() {
            translate([side * (hook_w/2 + gusset_flare - 0.5), plate_t, 0])
                cube([0.5, 0.5, arm_bottom_z + hook_t + gusset_height * 0.3]);
            translate([side * hook_w/2, plate_t, 0])
                cube([0.1, 5, arm_bottom_z]);
        }
    }
}

// Decorative/structural chamfer at arm-plate junction (bottom)
module bottom_fillet() {
    translate([-hook_w/2, plate_t, 0]) {
        // Smooth transition
        hull() {
            cube([hook_w, 8, 0.5]);
            translate([0, 0, arm_bottom_z - 0.5])
                cube([hook_w, 0.5, 0.5]);
        }
    }
}

// === Assembly ===
difference() {
    union() {
        wall_plate();
        hook_body();
        gusset();
        bottom_fillet();
    }
    screw_hole();

    // Trim anything behind the wall plate (behind y=0)
    translate([-50, -50, -10])
        cube([100, 50, 100]);
}
'}

{'content': '// Wall-mounted Towel Hook - M3 flat head screw mounting
// Designed for robust 3D printing (FDM)
// Print orientation: plate flat on bed

$fn = 100;

// === Parameters ===
plate_w = 34;           // Mounting plate width
plate_h = 55;           // Mounting plate height
plate_t = 5;            // Mounting plate thickness
plate_r = 5;            // Corner radius

hook_w = 22;            // Hook body width
hook_arm_len = 32;      // Arm length from wall
hook_t = 8;             // Hook cross-section thickness
hook_curve_r = 13;      // J-curve inner radius
hook_tip_len = 20;      // Upward tip length
hook_tip_angle = 12;    // Outward lean of tip (degrees)
arm_z = 5;              // Z of arm bottom edge

gusset_depth = 18;      // Gusset along arm
gusset_height = 22;     // Gusset up the plate

m3_clear = 3.4;
m3_head_d = 6.8;
m3_head_depth = 2.0;
screw_z = plate_h - 15;

// === Modules ===

module wall_plate() {
    translate([0, plate_t/2, plate_h/2])
        rotate([90, 0, 0])
            linear_extrude(height=plate_t, center=true)
                offset(plate_r) offset(-plate_r)
                    square([plate_w, plate_h], center=true);
}

module screw_hole() {
    translate([0, 0, screw_z]) {
        rotate([-90, 0, 0])
            translate([0, 0, -1])
                cylinder(d=m3_clear, h=plate_t + 2);
        rotate([-90, 0, 0])
            translate([0, 0, -0.01])
                cylinder(d1=m3_head_d, d2=m3_clear, h=m3_head_depth + 0.01);
    }
}

// 2D J-hook profile in the YZ plane
module hook_profile_2d() {
    r_out = hook_curve_r + hook_t/2;
    r_in = hook_curve_r - hook_t/2;
    curve_y = plate_t + hook_arm_len;
    curve_z = arm_z + hook_t/2;

    // Horizontal arm
    translate([plate_t, arm_z])
        square([hook_arm_len, hook_t]);

    // 180° J-curve
    translate([curve_y, curve_z])
        difference() {
            circle(r=r_out);
            circle(r=r_in);
            translate([-r_out-1, 0])
                square([2*r_out+2, r_out+1]);
        }

    // Upward tip with slight outward angle
    tip_y = curve_y;
    tip_z = curve_z - r_out;
    translate([tip_y, tip_z])
        rotate(180 + hook_tip_angle)
            translate([-hook_t/2, 0])
                square([hook_t, hook_tip_len]);

    // Rounded tip cap
    translate([tip_y, tip_z])
        rotate(180 + hook_tip_angle)
            translate([0, hook_tip_len])
                circle(d=hook_t);
}

module hook_body() {
    rotate([90, 0, 90])
        translate([0, 0, -hook_w/2])
            linear_extrude(height=hook_w)
                hook_profile_2d();
}

// Reinforcement structure
module reinforcement() {
    arm_top = arm_z + hook_t;
    flare = (plate_w - hook_w) / 2;

    // Main triangular gusset (full hook width)
    translate([-hook_w/2, plate_t, arm_top])
        rotate([0, 90, 0])
            linear_extrude(height=hook_w)
                polygon([
                    [0, 0],
                    [0, gusset_depth],
                    [-gusset_height, 0]
                ]);

    // Side flare gussets - smoothly widen at the plate
    for (s = [-1, 1]) {
        hull() {
            // Narrow edge at the hook arm
            translate([s * hook_w/2, plate_t, arm_top])
                cube([0.01, gusset_depth * 0.4, 0.01]);
            translate([s * hook_w/2, plate_t, arm_z])
                cube([0.01, gusset_depth * 0.4, 0.01]);
            // Wide edge at the plate
            translate([s * (hook_w/2 + flare - 1), plate_t, arm_top + gusset_height * 0.6])
                cube([1, 0.01, 0.01]);
            translate([s * (hook_w/2 + flare - 1), plate_t, arm_z])
                cube([1, 0.01, 0.01]);
        }
    }

    // Bottom filler between plate and arm
    translate([-hook_w/2, plate_t, 0])
        cube([hook_w, 4, arm_z]);

    // Smooth fillet under the arm    
    translate([-hook_w/2, plate_t, 0])
        linear_extrude(height=hook_w)  // This would need rotation
            polygon([[0,0]]);  // placeholder
}

// Better reinforcement approach
module reinforcement_v2() {
    arm_top = arm_z + hook_t;
    flare = (plate_w - hook_w) / 2;

    // Upper triangular gusset - main structural element
    translate([-hook_w/2, plate_t, arm_top])
        rotate([0, 90, 0])
            linear_extrude(height=hook_w)
                polygon([
                    [0, 0],
                    [0, gusset_depth],
                    [-gusset_height, 0]
                ]);

    // Lower support block
    translate([-hook_w/2, plate_t, 0])
        cube([hook_w, 6, arm_z]);

    // Lower triangular gusset
    translate([-hook_w/2, plate_t, 0])
        rotate([0, 90, 0])
            linear_extrude(height=hook_w)
                polygon([
                    [0, 0],
                    [0, 6],
                    [arm_z, 0]
                ]);

    // Side wings that flare from hook width to plate width
    for (s = [-1, 1]) {
        // Upper side gusset
        hull() {
            translate([s > 0 ? hook_w/2 : -hook_w/2 - 0.01, plate_t, arm_top])
                cube([0.01, gusset_depth * 0.35, gusset_height * 0.5]);
            translate([s > 0 ? plate_w/2 - 1 : -plate_w/2, plate_t - 0.01, arm_top])
                cube([1, 0.01, gusset_height * 0.7]);
        }
    }
}

// === Assembly ===
difference() {
    union() {
        wall_plate();
        hook_body();
        reinforcement_v2();
    }
    screw_hole();

    // Clean cut behind wall plane
    translate([-60, -60, -10])
        cube([120, 60, 100]);
}
'}

{'content': '// =============================================
// Wall-mounted Towel Hook
// M3 flat head screw mounting
// Robust design for heavy towels
// Print: plate flat on bed, hook up
// =============================================

$fn = 100;

// === Dimensions ===
// Mounting plate
plate_w    = 34;
plate_h    = 55;
plate_t    = 5;
plate_r    = 5;

// Hook body
hook_w     = 22;       // Width of the hook arm
hook_len   = 32;       // Arm extension from wall
hook_t     = 8;        // Arm thickness (strong)
curve_r    = 13;       // Inner radius of J-curve
tip_len    = 20;       // Anti-slip tip length
tip_angle  = 12;       // Tip lean-back angle (degrees)
arm_z      = 5;        // Bottom of arm above plate bottom

// Structural reinforcement
gusset_along = 18;     // Gusset extent along arm
gusset_up    = 22;     // Gusset extent up the plate

// M3 Flat head screw
m3_shaft_d  = 3.4;     // Clearance
m3_head_d   = 6.8;     // Head diameter
m3_sink     = 2.0;     // Countersink depth
screw_z     = plate_h - 15;

// === Wall Plate ===
module wall_plate() {
    translate([0, plate_t/2, plate_h/2])
    rotate([90, 0, 0])
    linear_extrude(plate_t, center=true)
        offset(plate_r) offset(-plate_r)
            square([plate_w, plate_h], center=true);
}

// === Screw Hole with Countersink ===
module screw_hole() {
    translate([0, 0, screw_z]) {
        // Shaft through-hole
        rotate([-90, 0, 0])
            translate([0, 0, -0.5])
                cylinder(d=m3_shaft_d, h=plate_t + 1);
        // Countersink on back (y=0 face)
        rotate([-90, 0, 0])
            translate([0, 0, -0.01])
                cylinder(d1=m3_head_d, d2=m3_shaft_d, h=m3_sink);
    }
}

// === J-Hook 2D Profile (YZ plane) ===
module hook_2d() {
    ro = curve_r + hook_t/2;
    ri = curve_r - hook_t/2;
    cy = plate_t + hook_len;       // Curve center Y
    cz = arm_z + hook_t/2;        // Curve center Z

    // Straight arm
    translate([plate_t, arm_z])
        square([hook_len, hook_t]);

    // 180° curve
    translate([cy, cz])
    difference() {
        circle(r=ro);
        circle(r=ri);
        translate([-ro-1, 0]) square([2*ro+2, ro+1]);
    }

    // Anti-slip tip curving upward
    ty = cy;
    tz = cz - ro;
    translate([ty, tz])
    rotate(180 + tip_angle) {
        translate([-hook_t/2, 0])
            square([hook_t, tip_len]);
        translate([0, tip_len])
            circle(d=hook_t);
    }
}

module hook_body() {
    rotate([90, 0, 90])
    translate([0, 0, -hook_w/2])
    linear_extrude(hook_w)
        hook_2d();
}

// === Reinforcement ===
module reinforcement() {
    at = arm_z + hook_t;
    flare = (plate_w - hook_w) / 2;

    // Upper gusset triangle (full hook width)
    translate([-hook_w/2, plate_t, at])
    rotate([0, 90, 0])
    linear_extrude(hook_w)
        polygon([[0,0], [0, gusset_along], [-gusset_up, 0]]);

    // Lower fill + mini gusset
    translate([-hook_w/2, plate_t, 0])
        cube([hook_w, 5, arm_z]);

    translate([-hook_w/2, plate_t, 0])
    rotate([0, 90, 0])
    linear_extrude(hook_w)
        polygon([[0,0], [0, 5], [arm_z, 0]]);

    // Side flare wings (blend hook width to plate width)
    for (s = [-1, 1]) {
        mirror_x = s > 0 ? 0 : 1;
        mirror([mirror_x, 0, 0])
        hull() {
            // At hook edge, goes up most of gusset
            translate([hook_w/2, plate_t, 0])
                cube([0.01, gusset_along * 0.35, at + gusset_up * 0.5]);
            // At plate edge, tall but thin
            translate([plate_w/2 - 1.5, plate_t/2, 0])
                cube([1.5, plate_t/2 + 0.01, at + gusset_up * 0.65]);
        }
    }
}

// === Final Assembly ===
difference() {
    union() {
        wall_plate();
        hook_body();
        reinforcement();
    }
    screw_hole();

    // Trim behind wall (y < 0)
    translate([-60, -60, -10])
        cube([120, 60, 100]);
}
